  as x(brand text, family text, generation text, generation_code text, model text);

insert into public.processor_brands (nombre, activo)
select distinct s.brand, true from desktop_processor_source s
where not exists (select 1 from public.processor_brands b where b.nombre_normalizado = public.normalizar_nombre_catalogo(s.brand));

insert into public.processor_families (fk_marca_procesador_id, nombre, activo)
select distinct b.id, s.family, true from desktop_processor_source s
join public.processor_brands b on b.nombre_normalizado = public.normalizar_nombre_catalogo(s.brand)
where not exists (select 1 from public.processor_families f where f.fk_marca_procesador_id = b.id and f.nombre_normalizado = public.normalizar_nombre_catalogo(s.family));

insert into public.processor_generations (fk_processor_family_id, code, name, sort_order, is_active)
select f.id, s.generation_code, s.generation, row_number() over (partition by f.id order by s.generation_code)::smallint, true
from (select distinct brand, family, generation, generation_code from desktop_processor_source) s
join public.processor_brands b on b.nombre_normalizado = public.normalizar_nombre_catalogo(s.brand)
join public.processor_families f on f.fk_marca_procesador_id = b.id and f.nombre_normalizado = public.normalizar_nombre_catalogo(s.family)
where not exists (select 1 from public.processor_generations g where g.fk_processor_family_id = f.id and g.code = s.generation_code);

insert into public.processor_models (fk_familia_procesador_id, fk_processor_generation_id, nombre, alcance, fk_organizacion_id, activo)
select f.id, g.id, s.model, 'GLOBAL', null, true from desktop_processor_source s
join public.processor_brands b on b.nombre_normalizado = public.normalizar_nombre_catalogo(s.brand)
join public.processor_families f on f.fk_marca_procesador_id = b.id and f.nombre_normalizado = public.normalizar_nombre_catalogo(s.family)
join public.processor_generations g on g.fk_processor_family_id = f.id and g.code = s.generation_code
where not exists (select 1 from public.processor_models m where m.fk_familia_procesador_id = f.id and m.fk_organizacion_id is null and m.nombre_normalizado = public.normalizar_nombre_catalogo(s.model));

with source_models as (
 select distinct f.id as family_id, g.id as generation_id, s.model from desktop_processor_source s
 join public.processor_brands b on b.nombre_normalizado = public.normalizar_nombre_catalogo(s.brand)
 join public.processor_families f on f.fk_marca_procesador_id = b.id and f.nombre_normalizado = public.normalizar_nombre_catalogo(s.family)
 join public.processor_generations g on g.fk_processor_family_id = f.id and g.code = s.generation_code
)
insert into public.processor_specifications (fk_processor_model_id, desktop_supported, notebook_supported)
select m.id, true, false from source_models sm
join public.processor_models m on m.fk_familia_procesador_id = sm.family_id and m.fk_organizacion_id is null and m.nombre_normalizado = public.normalizar_nombre_catalogo(sm.model)
on conflict (fk_processor_model_id) do update set desktop_supported = true;

commit;
